// Gemini's response nests the actual answer here:
const responseText = $input.first().json.candidates[0].content.parts[0].text;

// Sometimes models wrap JSON in ```json ... ``` — strip that out just in case.
let cleanText = responseText.replace(/```json/g, "").replace(/```/g, "").trim();

let extractedData;
try {
  extractedData = JSON.parse(cleanText);
} catch (error) {
  // If parsing fails, return the raw text so we can see what went wrong
  // instead of the whole workflow silently breaking.
  extractedData = {
    error: "Could not parse Gemini's response as JSON",
    raw_response: cleanText
  };
}

return [{ json: extractedData }];

const data = $input.first().json;
   const checks = [];
   let hardFail = false;

   // Check 1: Vendor name present
   const vendorPresent = !!data.vendor;
   checks.push({ name: "Vendor name present", passed: vendorPresent });
   if (!vendorPresent) hardFail = true;

   // Check 2: Invoice number present
   const invoiceNumberPresent = !!data.invoice_number;
   checks.push({ name: "Invoice number present", passed: invoiceNumberPresent });
   if (!invoiceNumberPresent) hardFail = true;

   // Check 3: Total is present and a valid positive number
   const totalValid = data.total !== null && data.total !== undefined && data.total > 0;
   checks.push({ name: "Total is present and valid", passed: totalValid });
   if (!totalValid) hardFail = true;

   // Check 4: Line item math reconciles with the total (within a small tolerance)
   let mathValid = true;
   if (Array.isArray(data.line_items) && data.line_items.length > 0) {
     let lineItemSum = 0;
     data.line_items.forEach((item) => {
       const expected = (item.quantity || 0) * (item.unit_price || 0);
       if (item.amount !== undefined && item.amount !== null && Math.abs(expected - item.amount) > 0.5) {
         mathValid = false;
       }
       lineItemSum += item.amount || 0;
     });
     const expectedTotal = lineItemSum + (data.tax || 0);
     if (Math.abs(expectedTotal - (data.total || 0)) > 1) {
       mathValid = false;
     }
   } else {
     mathValid = false; // no line items at all is itself a hard fail
   }
   checks.push({ name: "Line item math reconciles with total", passed: mathValid });
   if (!mathValid) hardFail = true;

   // Check 5: Not a duplicate of a known past invoice
   // (Small hardcoded sample list standing in for a real database/Google Sheet —
   //  see the README's disclosed-limitations section.)
   const sampleLedger = [
     { vendor: "Acme Corp", invoice_number: "1001" },
     { vendor: "Bright Office Supplies", invoice_number: "2044" },
     { vendor: "Nova Consulting", invoice_number: "3312" }
   ];
   const isDuplicate = sampleLedger.some(
     (entry) => entry.vendor === data.vendor && entry.invoice_number === data.invoice_number
   );
   checks.push({ name: "Not a duplicate of a known past invoice", passed: !isDuplicate });
   if (isDuplicate) hardFail = true;

   return [{
     json: {
       ...data,
       tier1_checks: checks,
       tier1_passed: !hardFail
     }
   }];

const data = $input.first().json;
   let score = 100;
   let tier2_findings = [];

   // Same small sample list from the Completeness Gate, reused here to check
   // whether this vendor has appeared before.
   const sampleLedger = [
     { vendor: "Acme Corp", invoice_number: "1001" },
     { vendor: "Bright Office Supplies", invoice_number: "2044" },
     { vendor: "Nova Consulting", invoice_number: "3312" }
   ];

   // Signal 1: first-time vendor
   const vendorSeenBefore = sampleLedger.some((entry) => entry.vendor === data.vendor);
   if (!vendorSeenBefore) {
     score -= 5;
     tier2_findings.push("New vendor — not seen in past invoices");
   }

   // Signal 2: suspiciously round total (a very mild anomaly signal, not a red flag on its own)
   if (data.total && data.total % 100 === 0) {
     score -= 5;
     tier2_findings.push("Total is a suspiciously round number");
   }

   // Signal 3: minor rounding drift, smaller than what Tier 1 already tolerated as a hard fail
   let lineItemSum = 0;
   if (Array.isArray(data.line_items)) {
     data.line_items.forEach((item) => { lineItemSum += item.amount || 0; });
   }
   const expectedTotal = lineItemSum + (data.tax || 0);
   const drift = Math.abs(expectedTotal - (data.total || 0));
   if (drift > 0.01 && drift <= 1) {
     score -= 3;
     tier2_findings.push("Minor rounding difference between line items and total");
   }

   // Signal 4: invoice date oddities
   if (data.date) {
     const invoiceDate = new Date(data.date);
     const today = new Date();
     const daysDiff = (today - invoiceDate) / (1000 * 60 * 60 * 24);
     if (daysDiff < 0) {
       score -= 5;
       tier2_findings.push("Invoice date is in the future");
     } else if (daysDiff > 180) {
       score -= 5;
       tier2_findings.push("Invoice is older than 6 months");
     }
   }

   return [{
     json: {
       ...data,
       confidence_score: score,
       tier2_findings: tier2_findings
     }
   }];

